5.4 4. Pulling data out

5.4.1 4.1 Grab the fields you actually need
Don’t pull every field (especially not embedding, which is a large numeric vector per document) if you don’t need it. Use the fields argument to project server-side:
library(tidyverse)

report_cols &lt;- '{
    "_id": 1, "report_number": 1, "title": 1, "plain_text": 1,
    "description": 1, "tags": 1, "authors": 1, "language": 1,
    "source_domain": 1, "date_published": 1
  }'


reports &lt;- reports_conn$find(
  fields = report_cols) |&gt; as_tibble()

glimpse(reports)


5.4.2 4.2 Filter server-side
mongolite accepts standard MongoDB query syntax as a JSON string, e.g. to grab only English-language reports:
reports_en &lt;- reports_conn$find(
  query  = '{"language": "en"}',
  fields = '{"_id": 1, "report_number": 1, "title": 1, "plain_text": 1}'
) |&gt; as_tibble()
For more information on the query syntax visit, https://jeroen.github.io/mongolite/query-data.html#query-syntax


5.4.3 4.3 Pull the incidents and join on report_number
incidents$reports is an array of report_numbers, not embedded report documents, so joining means unnesting that array and matching it up:
incidents &lt;- incidents_conn$find(
  fields = '{
    "_id": 1, "incident_id": 1, "title": 1, "description": 1, "date": 1,
    "reports": 1, "Alleged deployer of AI system": 1,
    "Alleged developer of AI system": 1,
    "Alleged harmed or nearly harmed parties": 1
  }'
) |&gt; as_tibble()

# one row per (incident_id, report_number) pair
incident_report_map &lt;- incidents |&gt;
  select(incident_id, reports) |&gt;
  unnest_longer(reports) |&gt;
  rename(report_number = reports)

# now every report row can carry its incident's metadata
reports_with_incident &lt;- reports |&gt;
  left_join(incident_report_map, by = "report_number") |&gt;
  left_join(
    incidents |&gt; select(incident_id, incident_title = title, date),
    by = "incident_id"
  )


5.4.4 4.4 Aggregation pipelines (optional, for heavier lifting)
For grouping/counting server-side before pulling data down:
reports_per_year &lt;- reports_conn$aggregate('[
  { "$group": {
      "_id": { "$substr": ["$date_published", 0, 4] },
      "n": { "$sum": 1 }
  }},
  { "$sort": { "_id": 1 } }
]') |&gt; as_tibble()


5.4.5 4.5 Other nested/array fields
Several fields come back from mongolite as list-columns: authors, submitters, tags (on reports); the “alleged deployer/developer/harmed parties” fields (on incidents). Each of these is a simple array of strings per document, so unnest_longer() is usually what you want (not unnest_wider(), which is for nested objects):
reports_authors &lt;- reports |&gt;
  select(report_number, authors) |&gt;
  unnest_longer(authors)   # one row per (report_number, author)

incidents_parties &lt;- incidents |&gt;
  select(incident_id, `Alleged harmed or nearly harmed parties`) |&gt;
  unnest_longer(`Alleged harmed or nearly harmed parties`) |&gt;
  rename(harmed_party = `Alleged harmed or nearly harmed parties`)
Guard against missing/empty text before tokenising:
reports &lt;- reports |&gt;
  mutate(plain_text = replace_na(plain_text, ""))

5.5 5. Cleaning the text
plain_text is already stripped of most markup, but scraped news text still tends to carry boilerplate (bylines, “read more” links, share-button text). Do a light cleaning pass and keep the original column in case later analysis needs it:






Warning



The following is only a suggestion and is not guaranteed to produce fully cleaned text ready for analysis.


library(textclean)

reports &lt;- reports |&gt;
  mutate(
    text_clean = plain_text |&gt;
      replace_contraction() |&gt;          # "don't" -&gt; "do not"
      replace_url() |&gt;
      replace_html() |&gt;
      str_squish()                       # trim/collapse whitespace
  )

5.6 6. Tokenising with tidytext
tidytext works on the “one-token-per-row” principle, which plugs directly into dplyr/ggplot2.
library(tidytext)

tokens &lt;- reports |&gt;
  select(report_number, text_clean) |&gt;
  unnest_tokens(word, text_clean)

# remove stop words
tokens_clean &lt;- tokens |&gt;
  anti_join(stop_words, by = "word")

5.6.1 6.1 Word frequencies
top_words &lt;- tokens_clean |&gt;
  count(word, sort = TRUE)

top_words |&gt;
  slice_max(n, n = 20) |&gt;
  ggplot(aes(x = reorder(word, n), y = n)) +
  geom_col() +
  coord_flip() +
  labs(x = NULL, y = "count", title = "Most frequent words across reports")


5.6.2 6.2 TF-IDF (which words distinguish one incident/domain from another)
This is a natural fit here: use incident_id or source_domain as the grouping variable to see what language is distinctive to a given incident or outlet.
tfidf &lt;- reports_with_incident |&gt;
  select(report_number, incident_id, text_clean) |&gt;
  unnest_tokens(word, text_clean) |&gt;
  anti_join(stop_words, by = "word") |&gt;
  count(incident_id, word, sort = TRUE) |&gt;
  bind_tf_idf(word, incident_id, n)

tfidf |&gt;
  group_by(incident_id) |&gt;
  slice_max(tf_idf, n = 10) |&gt;
  ungroup()


5.6.3 6.3 N-grams
For phrase-level patterns rather than single words:
bigrams &lt;- reports |&gt;
  unnest_tokens(bigram, text_clean, token = "ngrams", n = 2) |&gt;
  separate(bigram, into = c("word1", "word2"), sep = " ") |&gt;
  filter(!word1 %in% stop_words$word, !word2 %in% stop_words$word) |&gt;
  count(word1, word2, sort = TRUE)

5.7 7. Sentiment analysis
tidytext bundles several sentiment lexicons (bing, afinn, nrc, loughran). Join tokens to a lexicon the same way you joined stop words. loughran is worth knowing about here specifically — it was built for financial/news text and includes categories like “uncertainty” and “litigious”, which can be more informative than generic positive/negative for news-style incident reports.
sentiment_scores &lt;- tokens_clean |&gt;
  inner_join(get_sentiments("bing"), by = "word") |&gt;
  count(report_number, sentiment) |&gt;
  pivot_wider(names_from = sentiment, values_from = n, values_fill = 0) |&gt;
  mutate(net_sentiment = positive - negative)
For a numeric score per word (rather than positive/negative labels), use afinn:
afinn_scores &lt;- tokens_clean |&gt;
  inner_join(get_sentiments("afinn"), by = "word") |&gt;
  group_by(report_number) |&gt;
  summarise(sentiment_score = sum(value), .groups = "drop")
get_sentiments() will prompt a one-time download/license confirmation the first time you use a given lexicon — do this well before the competition starts, not on the day, in case you don’t have internet access at the venue.

5.8 8. Word co-occurrence / correlation (optional, widyr)
Useful for exploring which words tend to appear together within the same report:
library(widyr)

word_pairs &lt;- tokens_clean |&gt;
  pairwise_count(word, report_number, sort = TRUE)

word_cors &lt;- tokens_clean |&gt;
  group_by(word) |&gt;
  filter(n() &gt;= 20) |&gt;          # drop very rare words first
  pairwise_cor(word, report_number, sort = TRUE)

5.9 9. Putting it together: a minimal end-to-end script
library(mongolite)
library(tidyverse)
library(tidytext)
library(textclean)

db_name &lt;- "your_database_name"
reports_conn &lt;- mongo(collection = "reports", db = db_name,
                       url = Sys.getenv("MONGO_URI"))

reports &lt;- reports_conn$find(
  fields = '{"_id": 1, "report_number": 1, "title": 1, "plain_text": 1, "tags": 1}'
) |&gt;
  as_tibble() |&gt;
  mutate(
    plain_text = replace_na(plain_text, ""),
    text_clean = str_squish(replace_contraction(replace_url(plain_text, "")))
  )

word_counts &lt;- reports |&gt;
  unnest_tokens(word, text_clean) |&gt;
  anti_join(stop_words, by = "word") |&gt;
  count(word, sort = TRUE)

word_counts |&gt; slice_max(n, n = 15)

6.2 If you want to find latent themes: topic modeling (LDA)
library(topicmodels)

dtm &lt;- tokens_clean |&gt;
  count(report_number, word) |&gt;
  cast_dtm(report_number, word, n)

lda_model &lt;- LDA(dtm, k = 5, control = list(seed = 1234))

tidy(lda_model, matrix = "beta") |&gt;   # word probabilities per topic
  group_by(topic) |&gt;
  slice_max(beta, n = 10)
tidy() converts the model back into a tidy data frame so the rest of your dplyr/ggplot2 pipeline still applies. See Text Mining with R, Ch. 6.
